fn hv(i: i32) -> i32 {
    let s: i32 = i * 1103515245 + 12345;
    (s >> 16) & 32767
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x0b0b0b);
    let base: i32 = h - 50;
    let mut i: i32 = 0;
    while i < 5 {
        let mean: i32 = hv(i * 2) % 41 + 30;
        let spread: i32 = hv(i * 2 + 1) % 16 + 5;
        let x: i32 = 40 + i * (w - 80) / 4;
        let ylo: i32 = base - (mean - spread) * 3;
        let yhi: i32 = base - (mean + spread) * 3;
        host::display::draw_line(x, ylo, x, yhi, 0x909090);
        host::display::draw_line(x - 6, ylo, x + 6, ylo, 0x909090);
        host::display::draw_line(x - 6, yhi, x + 6, yhi, 0x909090);
        host::display::fill_rect(x - 3, base - mean * 3 - 3, 7, 7, 0x40c0ff);
        host::display::draw_number(x - 4, base + 10, i + 1, 0x808080, 2);
        i = i + 1;
    }
    host::display::draw_line(20, base, w - 20, base, 0x606060);
    host::display::draw_string(20, 12, "MEAN + SPREAD", 0x808080, 1);
    host::display::present();
}
